import {z as zod} from 'zod/v4';
import type mongoose from 'mongoose';
import {PrettifyType} from './index.js';

export interface SchemaFeatures {
  default?: any;
  required?: boolean;
  isOptional?: boolean;
  isExactOptional?: boolean;
  isNonOptional?: boolean;
  isNullable?: boolean;
  readOnly?: boolean;
  checks?: any;
  transformations?: any[];
}

/** Mongoose's closest equivalent to a Zod object's unknown-key policy. */
export function objectStrictness(schema: zod.ZodObject<any>): boolean | 'throw' {
  const catchall = (schema as any)._zod?.def?.catchall;
  if (!catchall) return true;
  return catchall._zod?.def?.type === 'never' ? 'throw' : false;
}

/**
 * Recursively unwrap Zod schemas (Optional, Nullable, Default, Effects, Pipelines)
 * using Zod's public API and internal _def.type identifiers.
 */
export function unwrapZodSchema(
  schema: zod.ZodTypeAny,
  // eslint-disable-next-line unicorn/no-object-as-default-parameter
  features: SchemaFeatures = {required: true},
  visited: Set<zod.ZodTypeAny> = new Set(),
): {schema: zod.ZodTypeAny; features: SchemaFeatures} {
  if (!schema) return {schema, features};
  if (visited.has(schema)) return {schema, features};

  const def = (schema as any)._def;
  if (!def) return {schema, features};

  // Skip visited check for wrappers to allow deep unwrapping
  if (
    !(schema instanceof zod.ZodOptional) &&
    !(schema instanceof zod.ZodNullable) &&
    !(schema instanceof zod.ZodDefault) &&
    def.type !== 'pipe'
  ) {
    visited.add(schema);
  }

  if (schema instanceof zod.ZodOptional) {
    const inner = schema.unwrap();
    const result = unwrapZodSchema(
      // @ts-expect-error Zod v4 schema.unwrap() return type mismatch
      inner,
      features,
      visited,
    );
    return {
      schema: result.schema,
      features: {
        ...result.features,
        required: false,
        isOptional: true,
        isExactOptional: false,
        isNonOptional: false,
      },
    };
  }

  if (schema instanceof zod.ZodExactOptional) {
    const result = unwrapZodSchema(schema.unwrap() as zod.ZodTypeAny, features, visited);
    return {
      schema: result.schema,
      features: {
        ...result.features,
        required: false,
        isOptional: true,
        isExactOptional: true,
        isNonOptional: false,
      },
    };
  }

  if (schema instanceof zod.ZodNonOptional) {
    const result = unwrapZodSchema(schema.unwrap() as zod.ZodTypeAny, features, visited);
    return {
      schema: result.schema,
      features: {
        ...result.features,
        required: true,
        isOptional: false,
        isExactOptional: false,
        isNonOptional: true,
      },
    };
  }

  if (schema instanceof zod.ZodNullable) {
    return unwrapZodSchema(
      // @ts-expect-error Zod v4 schema.unwrap() return type mismatch
      schema.unwrap(),
      {
        ...features,
        isNullable: true,
      },
      visited,
    );
  }

  if (schema instanceof zod.ZodDefault) {
    const defaultValue =
      typeof def.defaultValue === 'function' ? def.defaultValue() : def.defaultValue;
    return unwrapZodSchema(
      def.innerType,
      {
        ...features,
        default: defaultValue,
      },
      visited,
    );
  }

  const {type} = def;

  // In Zod v4, transform, preprocess, and refine are often implemented as pipes.
  // For transform: in = schema, out = transformation
  // For preprocess: in = preprocessing, out = schema
  if (type === 'pipe') {
    const inType = def.in?._def?.type;
    const outType = def.out?._def?.type;

    if (inType === 'transform') {
      // It's a preprocess (in is transformation, out is schema)
      return unwrapZodSchema(def.out, features, visited);
    }

    if (outType === 'transform' || outType === 'refinement') {
      // It's a transform or refine (in is schema, out is logic)
      // We should still collect transformations from the 'out' part
      const transformFeatures = {...features};
      const outDef = def.out?._def;
      const effects =
        outDef?.effects || outDef?.transformations || (outType === 'transform' ? [outDef] : []);
      if (effects && Array.isArray(effects)) {
        transformFeatures.transformations = [
          ...(transformFeatures.transformations || []),
          ...effects,
        ];
      }
      return unwrapZodSchema(def.in, transformFeatures, visited);
    }

    // Default pipe behavior (extract the output part)
    return unwrapZodSchema(def.out, features, visited);
  }

  if (
    type === 'transform' ||
    type === 'preprocess' ||
    type === 'refinement' ||
    type === 'effects'
  ) {
    const transformFeatures = {...features};
    const effects =
      def.effects ||
      def.transformations ||
      (def.type === 'transform' || type === 'transform' ? [def] : []);
    if (effects && Array.isArray(effects)) {
      transformFeatures.transformations = [
        ...(transformFeatures.transformations || []),
        ...effects,
      ];
    }
    const inner = def.schema || def.innerType;
    if (inner) {
      const result = unwrapZodSchema(inner, transformFeatures, visited);
      return result;
    }
  }

  if (type === 'lazy') {
    // For lazy types, we need to be careful with infinite recursion.
    // If we've already seen this specific lazy schema in this unwrapping chain,
    // we return it as is to stop recursion.
    // NOTE: In Zod v4, getter() might return different objects each time if not careful.
    return {schema, features};
  }

  if (type === 'branded' || type === 'readonly') {
    return unwrapZodSchema(
      (schema as any).unwrap(),
      {
        ...features,
        ...(type === 'readonly' ? {readOnly: true} : {}),
      },
      visited,
    );
  }

  // Extract checks if present
  if (def.checks && Array.isArray(def.checks)) {
    features.checks = [...(features.checks || []), ...def.checks];
  }

  return {schema, features};
}

/** @deprecated Use InferInput<T> instead. This alias will be removed in v4. */
export type InputMongoose<T> = zod.input<T>;

/** @deprecated Use InferDocument<T> instead. This alias will be removed in v4. */
export type OutputMongoose<T> = T extends {_zod: {output: any}}
  ? PrettifyType<Omit<zod.output<T>, '_id'> & {_id: mongoose.Types.ObjectId}>
  : unknown;

/** @deprecated Use InferDocument<T> instead. This alias will be removed in v4. */
export type InferMongoose<T> = OutputMongoose<T>;

/** The persisted Mongoose document represented by a Zod schema. */
export type InferDocument<T> = OutputMongoose<T>;

/** The raw input accepted by a Zod schema, before Mongoose adds document fields. */
export type InferInput<T> = InputMongoose<T>;
